 */
export function taskTitle(harness: string, title: string): string | null {
	if (harness === "pi") {
		const parts = title.split(" - ");
		if (parts.length < 3) return null;
		const session = parts.slice(1, -1).join(" - ").trim();
		return session || null;
	}
	/* 스피너(`✳`, `⠂`, …)는 글자가 아니므로 앞쪽 비문자·비숫자를 전부 떼어 낸다. */
