/** `workerFallbacks` · `leadFallbacks`: 주 모델이 시작 전에 거부하거나 말이 없으면 그 순서대로 한 번씩 다시 돈다. */
export type ModelSelection = {
	worker: RoleModel;
	lead: RoleModel;
	workerFallbacks: RoleModel[];
	leadFallbacks: RoleModel[];
	/** 역할 하네스의 `tiers.json` 목록에서 쓸 등급 범위: 작업마다 그 안에서 고른다(서버 `tiered.rs`).
	 *  서버가 내려주는 `worker` · `lead` 는 이미 등급을 푼 값이다. 없으면 위 모델을 그대로 쓴다. */
	workerTiers?: { from: string; to: string };
	leadTiers?: { from: string; to: string };
};

/** 한 역할이 주 모델 말고 더 고를 수 있는 수. */
export const MAX_FALLBACKS = 5;

export const CLAUDE_EFFORTS = ["low", "medium", "high", "xhigh", "max"] as const;
export const DEFAULT_MODELS: ModelSelection = {
	worker: { harness: "pi", model: "opencode-go/deepseek-v4.1-flash", effort: "high" },
	lead: { harness: "claude", model: "Opus 5.5", effort: "medium" },
	workerFallbacks: [],
	leadFallbacks: [],
};

export function modelItems(harness: Harness, providers: PiProvider[], current?: string): PiPickerItem[] {
	/* 목록과 저장값은 화면 이름(`name`)이다. CLI id로는 서버가 바꾼다. */
	if (harness === "claude") return claudeCatalog.models.map((model) => ({ value: model.name, group: "Claude Code" }));
	return withCurrentModel(piPickerItems(providers), providers, current);
}

export function effortsFor(harness: Harness, providers: PiProvider[], model: string): string[] {
	if (harness === "claude") return [...CLAUDE_EFFORTS];
	return piEffortsFor(providers, model);
}

/** 하네스나 모델을 바꾸면 없는 effort를 가장 가까운 지원 레벨로 내린다(Pi `clampThinkingLevel` 규칙). */
export function clampEffort(harness: Harness, providers: PiProvider[], model: string, effort: string): string {
	return clampPiEffort(effortsFor(harness, providers, model) as PiEffort[], effort);
}

/** 하네스를 바꾸면 그 하네스의 첫 모델로 옮긴다. 같은 하네스로 돌아오면 기본값. */
export function switchHarness(
	role: RoleModel,
	harness: Harness,
	providers: PiProvider[],
	fallback: RoleModel,
): RoleModel {
	if (role.harness === harness) return role;
	const items = modelItems(harness, providers);
	const model = fallback.harness === harness ? fallback.model : (items[0]?.value ?? "");
	return { harness, model, effort: clampEffort(harness, providers, model, role.effort) };
}

/** 추가할 모델 하나: 주 모델과 이미 고른 모델을 빼고, 주 모델의 하네스에서 아직 안 쓴 모델을 고른다.
 *  그 하네스가 다 썼으면 반대 하네스로 넘어간다. 없으면 추가할 수 없다. */
export function nextFallback(primary: RoleModel, taken: RoleModel[], providers: PiProvider[]): RoleModel | null {
	const used = (model: string) => model === primary.model || taken.some((entry) => entry.model === model);
	const other: Harness = primary.harness === "pi" ? "claude" : "pi";
	for (const harness of [primary.harness, other] as Harness[]) {
		const model = modelItems(harness, providers).find((item) => !used(item.value))?.value;
		if (model)
			return {
				harness,
				model,
				effort: clampEffort(harness, providers, model, primary.effort),
			};
	}
	return null;
}

/** 컴포저 필: `pi · deepseek-v4.1-flash · high`. provider 접두사는 title로만 남는다. */
export function shortModel(role: RoleModel): string {
	const name = role.harness === "claude" ? role.model : role.model.split("/").slice(1).join("/") || role.model;
	return `${role.harness} · ${name} · ${role.effort}`;
}

export function fullModel(role: RoleModel): string {
	return `${role.harness} ${role.model} (${role.effort})`;
}

