/**
 * 터미널 제목에서 지금 하는 일만 남긴다.
 *
 * - `claude`: 앞의 스피너 글리프를 떼고, 기본 제목(`Claude Code`)은 일이 아니므로 버린다.
 * - `pi`: `앱 - 세션 - 폴더`에서 가운데 세션 이름만 남긴다. 세션이 없으면 버린다.
 */
export function taskTitle(harness: string, title: string): string | null {
	if (harness === "pi") {
		const parts = title.split(" - ");
		if (parts.length < 3) return null;
		const session = parts.slice(1, -1).join(" - ").trim();
		return session || null;
	}
	/* 스피너(`✳`, `⠂`, …)는 글자가 아니므로 앞쪽 비문자·비숫자를 전부 떼어 낸다. */
	const name = title.replace(/^[^\p{L}\p{N}]+/u, "").trim();
	if (!name || name === "Claude Code") return null;
	return name;
}
